<?php
require __DIR__ . '/config.php';
$error=''; $sent=isset($_GET['sent']);
if ($_SERVER['REQUEST_METHOD']==='POST') {
  $name=trim($_POST['seller_name']??''); $phone=trim($_POST['phone']??''); $brand=trim($_POST['brand']??''); $model=trim($_POST['model']??''); $condition=$_POST['condition_label']??'Օգտագործված'; $price=trim($_POST['desired_price']??''); $details=trim($_POST['details']??'');
