  else { $stmt=$pdo->prepare('INSERT INTO sell_requests (seller_name,phone,brand,model,condition_label,desired_price,details) VALUES (?,?,?,?,?,?,?)'); $stmt->execute([$name,$phone,$brand,$model,$condition,(float)$price,$details]); header('Location: sell.php?sent=1'); exit; }
}
